package com.masalewala.api.controller;
import com.masalewala.api.repository.Repositories.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class CatalogController{private final Products products;private final Categories categories;private final Reviews reviews;CatalogController(Products p,Categories c,Reviews r){products=p;categories=c;reviews=r;}@GetMapping("/products") Object products(@RequestParam(defaultValue="") String q){return q.isBlank()?products.findAll():products.findByNameContainingIgnoreCase(q);}@GetMapping("/products/{id}") Object product(@PathVariable Long id){return products.findById(id).orElseThrow();}@GetMapping("/categories") Object categories(){return categories.findAll();}@GetMapping("/reviews") Object reviews(){return reviews.findAll();}}
